<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { MediaQuery } from 'svelte/reactivity';
  import { game } from '../../gameManager.ts';
  import { POKEMON_POOL, RARITY, type RarityId } from '../../constants/core.ts';
  import { EGG_DEX_REGION_THRESHOLDS, filterEggSpeciesNamesForProgress, getEggNativeRegionIdForSpecies } from '../../constants/balance/eggRegionMap.ts';
  import { resources } from '../stores/resources.svelte.ts';
  import { team } from '../stores/team.svelte.ts';
  import { GameEventType } from '../bus/events.ts';
  import { formatNumber, getShardKey } from '../../formatters.ts';
  import { SHADOW_STAT_MULTS, SHINY_STAT_MULT } from '../../constants/balance/creatureVariants.ts';
  import { GEN5_SUBSTITUTE_SPRITE, getPokemonSpriteUrl } from '../lib/cardSprites.ts';
  import { getRegionDisplayName } from '../lib/starterModalPresentation.ts';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { uiPokemonNameText } from '../ui/i18n.ts';
  import {
    analyzeSpecialIncubatorDna,
    cancelSpecialIncubatorPreheat,
    getSpecialIncubatorCatalyst,
    getSpecialIncubatorDustQuote,
    getSpecialIncubatorProgressGoal,
    getSpecialIncubatorTowerFloor,
    injectSpecialIncubatorCatalyst,
    promoteSpecialIncubatorPreheat,
    queueSpecialIncubatorPreheat,
    specialIncubatorIvTotal,
    specialIncubatorMasteryLevel,
    specialIncubatorPreheatCapacity,
    specialIncubatorPreheatProgress,
    specialIncubatorProtocolBonus,
    specialIncubatorTemplateEligible,
    subscribeSpecialIncubators,
    VAT_CATALYST_LIMIT,
    VAT_ACTIVITY_POINTS,
    VAT_DNA_LEVEL,
    VAT_DNA_REROLLS,
    VAT_HATCH_PROGRESS,
    VAT_MASTERY_THRESHOLDS,
    VAT_MEMORY_PROGRESS_REDUCTION,
    VAT_PREHEAT_MAX,
    VAT_PREHEAT_SOURCE_LIMIT,
    VAT_PREHEAT_UNLOCK_LEVEL,
    VAT_PROTOCOL_BONUS,
    VAT_PROTOCOL_LEVEL,
    VAT_TRIPLE_PREHEAT_LEVEL,
    type SpecialIncubatorCatalyst,
    type SpecialIncubatorJob,
    type SpecialIncubatorPreheat,
    type SpecialVatId,
  } from '../../specialIncubatorSystem.ts';
  import type { CreatureData } from '../types/creature.js';

  const PICKER_TILE_HEIGHT = 112;
  const PICKER_GAP = 6;
  const PICKER_ROW = PICKER_TILE_HEIGHT + PICKER_GAP;
  const PICKER_MIN_COL = 100;
  const PICKER_OVERSCAN = 1;
  const SHINY_BONUS = Math.round((SHINY_STAT_MULT - 1) * 100);
  const SHADOW_HP = Math.round((SHADOW_STAT_MULTS.hp - 1) * 100);
  const SHADOW_ATK = Math.round((SHADOW_STAT_MULTS.atk - 1) * 100);
  const SHADOW_DEF = Math.round((SHADOW_STAT_MULTS.def - 1) * 100);
  const SHADOW_SPD = Math.round((SHADOW_STAT_MULTS.spd - 1) * 100);
  const IV_STATS = [
    ['ivHP', 'specialIncubators.dnaHp', 'PV'],
    ['ivAttack', 'modal.creature.atkShort', 'ATK'],
    ['ivSpAttack', 'modal.creature.spAtkShort', 'ATK SP'],
    ['ivDefense', 'modal.creature.defShort', 'DEF'],
    ['ivSpDefense', 'modal.creature.spDefShort', 'DEF SP'],
    ['ivSpeed', 'modal.creature.speedShort', 'SPD'],
  ] as const;
  const MASTERY_PERKS = ['preheat', 'protocol', 'dna', 'triple', 'memory'] as const;
  type MasteryPerk = typeof MASTERY_PERKS[number];
  const EGG_LABELS = {
    common: 'Œuf commun', rare: 'Œuf rare', epic: 'Œuf épique', legendary: 'Œuf légendaire',
  } as const;
  const vats = ['chromatic', 'shadow'] as const;
  const mobile = new MediaQuery('(max-width: 720px)');

  type Activity = keyof typeof VAT_ACTIVITY_POINTS;
  const PICKER_SORT_OPTIONS = [
    { key: 'name', labelKey: 'pickerSortName', fallback: 'Nom' },
    { key: 'level', labelKey: 'pickerSortLevel', fallback: 'Niveau' },
    { key: 'rarity', labelKey: 'pickerSortRarity', fallback: 'Rareté' },
    { key: 'shards', labelKey: 'pickerSortShards', fallback: 'Shards de famille' },
    { key: 'shiny', labelKey: 'pickerSortShiny', fallback: 'Chromatiques' },
    { key: 'shadow', labelKey: 'pickerSortShadow', fallback: 'Ombres' },
  ] as const;
  type PickerSort = typeof PICKER_SORT_OPTIONS[number]['key'];
  const RARITY_RANK: Record<string, number> = { common: 0, rare: 1, epic: 2, legendary: 3 };
  type EggCandidate = { species: string; rarity: RarityId };
  const eggsByFamily = new Map<string, EggCandidate[]>();
  for (const rarity of Object.values(RARITY)) {
    for (const species of Object.values(POKEMON_POOL[rarity] ?? {}).flat()) {
      const family = getShardKey(species, rarity);
      const candidates = eggsByFamily.get(family);
      if (candidates) candidates.push({ species, rarity });
      else eggsByFamily.set(family, [{ species, rarity }]);
    }
  }

  let tickCount = $state(0);
  let activeVat = $state<SpecialVatId>('chromatic');
  let aborting = $state<{ vat: SpecialVatId; uid: string } | null>(null);
  let abortTrigger: HTMLButtonElement | null = null;
  let picks = $state<Record<SpecialVatId, string>>({ chromatic: '', shadow: '' });
  let catalystQuantity = $state<Record<SpecialVatId, number | undefined>>({ chromatic: 1, shadow: 1 });
  let catalystStale = $state<Record<SpecialVatId, boolean>>({ chromatic: false, shadow: false });
  let picker = $state<{ vat: SpecialVatId; preheat: boolean } | null>(null);
  let pickerQuery = $state('');
  let pickerSort = $state<PickerSort>('name');
  let pickerDescending = $state(false);
  let pickerRarity = $state<RarityId | 'all'>('all');
  let pickerVariant = $state<'all' | 'normal' | 'shiny' | 'shadow'>('all');
  let pickerScroll = $state(0);
  let pickerCols = $state(4);
  let pickerViewport = $state(280);
  let pickerScrollNode: HTMLElement | null = null;
  let pickerSearchNode: HTMLInputElement | null = null;
  let pickerTrigger: HTMLElement | null = null;

  onMount(() => subscribeSpecialIncubators(refreshVats));
  useFacadeSubscription(GameEventType.MODAL_CLOSED, (event) => {
    if (event.type === GameEventType.MODAL_CLOSED && event.modalId === 'specialIncubatorModal') {
      dismissAbort();
      closePicker(false);
    }
  });

  function refreshVats(): void {
    tickCount += 1;
    if (aborting) {
      const job = game?.specialIncubatorState?.[aborting.vat];
      if (job?.creatureUid !== aborting.uid || job.progress >= progressGoal(storedCreatureByUid(job.creatureUid))) dismissAbort();
    }
  }

  function attachPickerScroll(node: HTMLElement): () => void {
    pickerScrollNode = node;
    const measure = () => {
      const width = node.clientWidth;
      const cols = Math.max(1, Math.floor((width + PICKER_GAP) / (PICKER_MIN_COL + PICKER_GAP)));
      const viewport = node.clientHeight || 280;
      if (cols !== pickerCols) pickerCols = cols;
      if (viewport !== pickerViewport) pickerViewport = viewport;
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => {
      observer.disconnect();
      if (pickerScrollNode === node) pickerScrollNode = null;
    };
  }

  function attachPickerSearch(node: HTMLInputElement): () => void {
    pickerSearchNode = node;
    node.focus();
    return () => {
      if (pickerSearchNode === node) pickerSearchNode = null;
    };
  }

  function attachPickerDialog(node: HTMLDialogElement): () => void {
    let startedOutside = false;
    const isOutside = (event: MouseEvent): boolean => {
      if (event.target !== node) return false;
      const rect = node.getBoundingClientRect();
      return event.clientX < rect.left || event.clientX > rect.right
        || event.clientY < rect.top || event.clientY > rect.bottom;
    };
    const onPointerDown = (event: PointerEvent) => {
      startedOutside = event.isPrimary && event.button === 0 && isOutside(event);
    };
    const onPointerCancel = () => { startedOutside = false; };
    const onClick = (event: MouseEvent) => {
      const close = startedOutside && isOutside(event);
      startedOutside = false;
      if (!close) return;
      event.preventDefault();
      event.stopPropagation();
      closePicker();
    };
    node.addEventListener('pointerdown', onPointerDown);
    node.addEventListener('pointercancel', onPointerCancel);
    node.addEventListener('click', onClick);
    node.showModal();
    return () => {
      node.removeEventListener('pointerdown', onPointerDown);
      node.removeEventListener('pointercancel', onPointerCancel);
      node.removeEventListener('click', onClick);
      node.close();
    };
  }

  function unescapeHtml(str: string): string {
    return str
      .replace(/&#39;/g, "'")
      .replace(/&quot;/g, '"')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
  }

  function t(key: string, fallback: string, vars: Record<string, string | number> = {}): string {
    if (!game?.t) return fallback;
    const got = game.t(key, vars);
    return unescapeHtml(got && got !== key ? got : fallback);
  }

  function catalystFor(job: SpecialIncubatorJob): SpecialIncubatorCatalyst | null {
    void resources.shards;
    return game ? getSpecialIncubatorCatalyst(game, job) : null;
  }

  function injectCatalyst(vat: SpecialVatId, preview: SpecialIncubatorCatalyst, quantity: number): void {
    if (!game) return;
    catalystStale[vat] = !injectSpecialIncubatorCatalyst(game, vat, preview, quantity);
    if (catalystStale[vat]) refreshVats();
  }

  function speciesRarity(creature: CreatureData): string {
    const defined = typeof game?.getPokemonBaseDefinition === 'function'
      ? game.getPokemonBaseDefinition(creature.name)
      : null;
    const rarity = defined?.rarity || creature.rarity || 'common';
    if (rarity === 'rare' || rarity === 'epic' || rarity === 'legendary') return rarity;
    return 'common';
  }

  function rarityLabel(rarity: string): string {
    if (game && typeof game.getRarityLabel === 'function') {
      const label = game.getRarityLabel(rarity);
      if (label) return label;
    }
    return t(`rarity.${rarity}`, rarity);
  }

  function masteryReward(perk: MasteryPerk): string {
    return t(`specialIncubators.masteryReward_${perk}`, perk, {
      slots: specialIncubatorPreheatCapacity(perk === 'triple' ? VAT_TRIPLE_PREHEAT_LEVEL : VAT_PREHEAT_UNLOCK_LEVEL),
      bonus: VAT_PROTOCOL_BONUS,
      rolls: VAT_DNA_REROLLS,
      reduction: VAT_MEMORY_PROGRESS_REDUCTION,
    });
  }

  function masteryRequirement(total: number): string {
    return t('specialIncubators.masteryRequirement', '{count} / {need} Exp.', {
      count: formatNumber(snapshot.completedExperiments), need: total,
    });
  }

  function spriteUrl(creature: CreatureData, shiny = !!creature.isShiny): string {
    return getPokemonSpriteUrl(creature.name, shiny);
  }

  function onSpriteError(event: Event): void {
    const img = event.currentTarget as HTMLImageElement;
    if (img.src !== GEN5_SUBSTITUTE_SPRITE) img.src = GEN5_SUBSTITUTE_SPRITE;
  }

  function onLabKey(event: KeyboardEvent): void {
    if (event.key !== 'Escape' || (!picker && !aborting)) return;
    if (!(event.target instanceof Element) || !event.target.closest('#specialIncubatorModal.show')) return;
    event.preventDefault();
    event.stopPropagation();
    if (picker) closePicker();
    else dismissAbort(true);
  }

  let snapshot = $derived.by(() => {
    void tickCount;
    const state = game?.specialIncubatorState;
    return {
      chromatic: state?.chromatic ?? null,
      shadow: state?.shadow ?? null,
      completedExperiments: state?.completedExperiments ?? 0,
      preheats: state?.preheats ?? [],
    };
  });
  let geneticsLevel = $derived(specialIncubatorMasteryLevel(snapshot.completedExperiments));
  let nextMasteryAt = $derived(VAT_MASTERY_THRESHOLDS[geneticsLevel]);
  let nextPerk = $derived(MASTERY_PERKS[geneticsLevel]);
  let preheatCapacity = $derived(specialIncubatorPreheatCapacity(geneticsLevel));

  function dustQuote(template: CreatureData | null): { baseCost: number; cost: number } {
    void tickCount;
    return game && template ? getSpecialIncubatorDustQuote(game, template) : { baseCost: 0, cost: 0 };
  }

  function progressGoal(template: CreatureData | null): number {
    void tickCount;
    return game ? getSpecialIncubatorProgressGoal(game, template) : VAT_HATCH_PROGRESS;
  }

  function preheatBlocker(preheat: SpecialIncubatorPreheat, template: CreatureData | null, cost: number): { label: string; description: string } | null {
    if (!template) return {
      label: t('specialIncubators.preheatMissingShort', 'Modèle absent'),
      description: t('specialIncubators.preheatMissing', 'Le modèle doit être au stockage pour poursuivre le préchauffage ou être transféré.'),
    };
    if (snapshot[preheat.vat]) return {
      label: t('specialIncubators.preheatBusyShort', 'Cuve occupée'),
      description: t('specialIncubators.preheatBusy', 'La cuve choisie est occupée.'),
    };
    if (preheat.vat === 'chromatic' ? template.isShiny : template.isShadow) return {
      label: t('specialIncubators.preheatVariantShort', 'Modèle déjà de cette variante'),
      description: t('specialIncubators.logAlreadyVariant', 'Ce modèle est déjà de cette variante.'),
    };
    if (essenceStock < cost) return {
      label: t('specialIncubators.preheatEssenceShort', 'Essence insuffisante'),
      description: t('specialIncubators.setupNeedEssence', 'Il manque {amount} poussière d’essence. Recycle des Shards dans le Recycleur.', {
        amount: formatNumber(cost - essenceStock, 2),
      }),
    };
    return null;
  }

  let essenceStock = $derived(resources.essenceDust || 0);

  function storedCreatures(): CreatureData[] {
    void tickCount;
    void team.storageRoster;
    const list = Array.isArray(game?.storage) ? game.storage : [];
    return list.filter((creature): creature is CreatureData => !!creature?.uid && !!creature.name);
  }

  function storageRows(vat: SpecialVatId): Array<{ index: number; uid: string; label: string }> {
    void tickCount;
    void team.storageRoster;
    if (!game) return [];
    const list = Array.isArray(game.storage) ? game.storage : [];
    const rows: Array<{ index: number; uid: string; label: string }> = [];
    list.forEach((creature, index) => {
      if (!specialIncubatorTemplateEligible(game, vat, creature)) return;
      rows.push({
        index,
        uid: String(creature.uid),
        label: `${creature.name} · ${t('state.levelShort', 'Nv.')} ${creature.level ?? 1}`,
      });
    });
    return rows;
  }

  function creatureAt(index: number): CreatureData | null {
    const list = Array.isArray(game?.storage) ? game.storage : [];
    return list[index] ?? null;
  }

  function storedCreatureByUid(uid: string | undefined): CreatureData | null {
    void team.storageRoster;
    if (!uid || !Array.isArray(game?.storage)) return null;
    return game.storage.find((creature) => creature && String(creature.uid) === uid) ?? null;
  }

  function refundDustLabel(vat: SpecialVatId, job: SpecialIncubatorJob): string {
    if (job.dustCurrency === 'essenceDust') return t('shop.essenceDustLabel', 'Poussière d’essence');
    return vat === 'chromatic'
      ? t('shop.shinyDustLabel', 'Poussière chromatique')
      : t('shop.shadowDustLabel', 'Poussière ombre');
  }

  function selectedCreature(vat: SpecialVatId): CreatureData | null {
    void tickCount;
    const creature = storedCreatureByUid(picks[vat]);
    return game && specialIncubatorTemplateEligible(game, vat, creature) ? creature : null;
  }

  function willFuse(vat: SpecialVatId, creature: CreatureData): boolean {
    void tickCount;
    void team.storageRoster;
    void team.playerTeam;
    void team.pension;
    const find = game?.findCreatureByName;
    if (typeof find !== 'function') return false;
    const existing = find.call(game, creature.name, vat === 'chromatic', vat === 'shadow');
    if (!existing?.uid) return false;
    return String(existing.uid) !== String(creature.uid);
  }

  function birthLine(vat: SpecialVatId): string {
    if (vat === 'chromatic') {
      return t(
        'specialIncubators.birthChromatic',
        '+{all} % à toutes les stats, IV neufs.',
        { all: SHINY_BONUS },
      );
    }
    return t(
      'specialIncubators.birthShadow',
      'PV +{hp} %, ATQ +{atk} %, DEF +{def} %, VIT +{spd} %, IV neufs.',
      { hp: SHADOW_HP, atk: SHADOW_ATK, def: SHADOW_DEF, spd: SHADOW_SPD },
    );
  }

  function vatTitle(vat: SpecialVatId): string {
    return vat === 'chromatic'
      ? t('specialIncubators.chromaticTitle', 'Cuve chromatique')
      : t('specialIncubators.shadowTitle', 'Cuve ombre');
  }

  function tabStatus(job: SpecialIncubatorJob | null): string {
    if (!job) return t('specialIncubators.tabFree', 'Libre');
    const goal = progressGoal(storedCreatureByUid(job.creatureUid));
    if (job.progress >= goal) return t('specialIncubators.tabReady', 'Prête');
    if (goal < VAT_HATCH_PROGRESS) return t('specialIncubators.progressRatio', '{progress} / {goal} %', { progress: job.progress, goal });
    return t('specialIncubators.percent', `${job.progress} %`, { value: job.progress });
  }

  function selectVat(vat: SpecialVatId): void {
    if (vat === activeVat) return;
    activeVat = vat;
    closePicker();
    dismissAbort();
  }

  async function openPicker(vat: SpecialVatId, preheat = false): Promise<void> {
    if (preheat ? snapshot.preheats.length >= preheatCapacity : snapshot[vat]) return;
    if (storageRows(vat).length === 0) return;
    pickerQuery = '';
    if ((vat === 'chromatic' && pickerSort === 'shiny') || (vat === 'shadow' && pickerSort === 'shadow')) {
      pickerSort = 'name';
      pickerDescending = false;
    }
    if ((vat === 'chromatic' && pickerVariant === 'shiny') || (vat === 'shadow' && pickerVariant === 'shadow')) {
      pickerVariant = 'all';
    }
    pickerTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    pickerScroll = 0;
    picker = { vat, preheat };
    await tick();
    if (pickerScrollNode) pickerScrollNode.scrollTop = 0;
    pickerSearchNode?.focus({ preventScroll: true });
  }

  async function closePicker(restoreFocus = true): Promise<void> {
    const trigger = pickerTrigger;
    pickerTrigger = null;
    picker = null;
    if (restoreFocus && trigger) {
      await tick();
      if (trigger.isConnected && trigger.closest('#specialIncubatorModal.show')) trigger.focus({ preventScroll: true });
    }
  }

  function resetPickerScroll(): void {
    pickerScroll = 0;
    if (pickerScrollNode) pickerScrollNode.scrollTop = 0;
  }

  function changePickerSort(key: PickerSort): void {
    if (pickerSort === key) pickerDescending = !pickerDescending;
    else {
      pickerSort = key;
      pickerDescending = key !== 'name';
    }
    resetPickerScroll();
  }

  function normalizePickerSearch(value: string): string {
    return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase();
  }

  function chooseRow(row: { uid: string }): void {
    if (!picker || !game) return;
    const { vat, preheat } = picker;
    if (preheat) {
      if (!queueSpecialIncubatorPreheat(game, vat, row.uid)) {
        refreshVats();
        return;
      }
    } else {
      picks[vat] = row.uid;
    }
    closePicker();
  }

  function onPickerScroll(event: Event): void {
    pickerScroll = (event.currentTarget as HTMLElement).scrollTop;
  }

  async function onPickerTileKey(event: KeyboardEvent, uid: string): Promise<void> {
    const index = pickerRows.findIndex((row) => row.uid === uid);
    if (index < 0) return;
    const next = event.key === 'ArrowRight' ? index + 1 : event.key === 'ArrowLeft' ? index - 1
      : event.key === 'ArrowDown' ? index + pickerCols : event.key === 'ArrowUp' ? index - pickerCols
      : event.key === 'Home' ? 0 : event.key === 'End' ? pickerRows.length - 1 : null;
    if (next === null || !pickerScrollNode) return;
    event.preventDefault();
    const targetIndex = Math.max(0, Math.min(pickerRows.length - 1, next));
    const target = pickerRows[targetIndex];
    if (!target) return;
    const top = Math.floor(targetIndex / pickerCols) * PICKER_ROW;
    if (top < pickerScrollNode.scrollTop) pickerScrollNode.scrollTop = top;
    else if (top + PICKER_TILE_HEIGHT > pickerScrollNode.scrollTop + pickerScrollNode.clientHeight) {
      pickerScrollNode.scrollTop = top + PICKER_TILE_HEIGHT - pickerScrollNode.clientHeight;
    }
    pickerScroll = pickerScrollNode.scrollTop;
    await tick();
    pickerScrollNode?.querySelector<HTMLButtonElement>(`[data-picker-uid="${CSS.escape(target.uid)}"]`)?.focus({ preventScroll: true });
  }

  function startVat(vat: SpecialVatId): void {
    const creature = selectedCreature(vat);
    if (!creature || !game) return;
    const index = game.storage.indexOf(creature);
    if (index < 0) return;
    const started = game.startSpecialIncubator(vat, index);
    if (started) resetVatControls(vat);
    tickCount += 1;
  }

  function resetVatControls(vat: SpecialVatId): void {
    picks[vat] = '';
    catalystQuantity[vat] = 1;
    catalystStale[vat] = false;
    if (picker?.vat === vat && !picker.preheat) closePicker();
  }

  function transferPreheat(entry: SpecialIncubatorPreheat): void {
    if (game && promoteSpecialIncubatorPreheat(game, entry.creatureUid)) resetVatControls(entry.vat);
  }

  function cancelVat(vat: SpecialVatId): void {
    if (game?.cancelSpecialIncubator(vat)) resetVatControls(vat);
    refreshVats();
  }

  function requestAbort(vat: SpecialVatId, trigger: HTMLButtonElement): void {
    const job = game?.specialIncubatorState?.[vat];
    if (!job || job.progress >= progressGoal(storedCreatureByUid(job.creatureUid))) return;
    if (!job.catalystShardsSpent) {
      cancelVat(vat);
      return;
    }
    abortTrigger = trigger;
    aborting = { vat, uid: job.creatureUid };
  }

  async function dismissAbort(restoreFocus = false): Promise<void> {
    const trigger = abortTrigger;
    aborting = null;
    abortTrigger = null;
    if (restoreFocus && trigger) {
      await tick();
      trigger.focus();
    }
  }

  function confirmAbort(vat: SpecialVatId): void {
    if (aborting?.vat === vat && aborting.uid === game?.specialIncubatorState?.[vat]?.creatureUid) cancelVat(vat);
    dismissAbort();
  }

  function claimVat(vat: SpecialVatId): void {
    game?.claimSpecialIncubator(vat);
    tickCount += 1;
  }

  function activityGain(source: Activity, job: SpecialIncubatorJob | null, contribution?: number): number {
    const bonus = job && geneticsLevel >= VAT_PROTOCOL_LEVEL ? specialIncubatorProtocolBonus(job, source) : 0;
    const goal = job ? progressGoal(storedCreatureByUid(job.creatureUid)) : VAT_HATCH_PROGRESS;
    const remaining = contribution !== undefined ? VAT_PREHEAT_SOURCE_LIMIT - contribution : goal - (job?.progress ?? 0);
    return Math.min(VAT_ACTIVITY_POINTS[source] + bonus, remaining);
  }

  function eggSource(family: string): { rarity?: RarityId; unavailable?: string } {
    void tickCount;
    const candidates = eggsByFamily.get(family);
    if (!candidates?.length) return { unavailable: t('specialIncubators.activityEggUnavailable', 'Famille absente des œufs') };

    const eligible = new Set(filterEggSpeciesNamesForProgress(game, candidates.map(({ species }) => species)));
    const first = candidates.find(({ species }) => eligible.has(species));
    if (first) return { rarity: first.rarity };

    const regions = new Set(candidates.map(({ species }) => getEggNativeRegionIdForSpecies(species)));
    const region = EGG_DEX_REGION_THRESHOLDS.find(({ regionId }) => regions.has(regionId));
    return {
      unavailable: region
        ? t('specialIncubators.activityEggLocked', `Œufs de ${getRegionDisplayName(region.regionId)} à débloquer`, {
          region: getRegionDisplayName(region.regionId),
        })
        : t('specialIncubators.activityEggUnavailable', 'Famille absente des œufs'),
    };
  }

  let pickerCandidates = $derived.by(() => {
    if (!picker) return [];
    void resources.shards;
    return storageRows(picker.vat).flatMap((row) => {
      const creature = creatureAt(row.index);
      if (!creature) return [];
      const name = uiPokemonNameText(game, creature.name);
      const rarity = speciesRarity(creature);
      const family = getShardKey(creature.name, rarity);
      return [{ ...row, name, rarity, level: creature.level ?? 1,
        isShiny: !!creature.isShiny, isShadow: !!creature.isShadow,
        shards: Math.max(0, Number(resources.shards[family]) || 0),
        search: normalizePickerSearch(`${name} ${creature.name}`),
      }];
    });
  });

  let pickerRows = $derived.by(() => {
    const query = normalizePickerSearch(pickerQuery.trim());
    const rows = pickerCandidates.filter((row) => {
      const variantMatches = pickerVariant === 'all'
        || (pickerVariant === 'normal' && !row.isShiny && !row.isShadow)
        || (pickerVariant === 'shiny' && row.isShiny)
        || (pickerVariant === 'shadow' && row.isShadow);
      return variantMatches && (pickerRarity === 'all' || row.rarity === pickerRarity)
        && (!query || row.search.includes(query));
    });
    const direction = pickerDescending ? -1 : 1;
    const collator = new Intl.Collator(game?.language === 'fr' ? 'fr' : 'en', { sensitivity: 'base', numeric: true });
    return rows.sort((a, b) => {
      const nameOrder = collator.compare(a.name, b.name);
      const order = pickerSort === 'name' ? nameOrder
        : pickerSort === 'level' ? a.level - b.level
        : pickerSort === 'rarity' ? (RARITY_RANK[a.rarity] ?? 0) - (RARITY_RANK[b.rarity] ?? 0)
        : pickerSort === 'shiny' ? Number(a.isShiny) - Number(b.isShiny)
        : pickerSort === 'shadow' ? Number(a.isShadow) - Number(b.isShadow)
        : a.shards - b.shards;
      return direction * order || nameOrder || a.index - b.index;
    });
  });

  let pickerWindow = $derived.by(() => {
    const rows = pickerRows;
    const cols = Math.max(1, pickerCols);
    const totalRows = Math.ceil(rows.length / cols);
    const startRow = Math.min(Math.max(0, totalRows - 1), Math.max(0, Math.floor(pickerScroll / PICKER_ROW) - PICKER_OVERSCAN));
    const visibleRows = Math.max(1, Math.ceil((pickerViewport || 280) / PICKER_ROW) + PICKER_OVERSCAN * 2);
    const endRow = Math.min(totalRows, startRow + visibleRows);
    return {
      items: rows.slice(startRow * cols, endRow * cols),
      top: startRow * PICKER_ROW,
      bottom: Math.max(0, (totalRows - endRow) * PICKER_ROW),
    };
  });
</script>

