              aria-haspopup="dialog" aria-expanded={picker?.vat === vat && !picker.preheat}
              onclick={() => openPicker(vat)}>
              {@render tubeContents(model, progress, goal)}
            </button>
          {:else}
            <div class="vat-chamber" aria-hidden="true">{@render tubeContents(model, progress, goal)}</div>
          {/if}
          <div class="vat-summary">
            <h3 id="special-incubator-{vat}">{title}</h3>
            {#if model}
              <p class="vat-picked">
                <strong>{uiPokemonNameText(game, model.name)}</strong>
                <span>{t('specialIncubators.templateLevel', 'Modèle · Nv. {level}', { level: model.level ?? 1 })}</span>
              </p>
              {@render resultVariant(vat, model)}
            {:else}
              <p class="vat-empty">{job
                ? t('specialIncubators.preheatMissing', 'Le modèle doit être au stockage.')
                : t('specialIncubators.tabFree', 'Libre')}</p>
            {/if}
            {#if job || model}
              <div class="vat-progress-group">
                <p class="vat-progress-label" aria-live="polite">
                  {goal < VAT_HATCH_PROGRESS
                    ? t('specialIncubators.progressMemory', 'Progression : {progress} / {goal} %', { progress, goal })
                    : t('specialIncubators.progress', 'Progression : {progress} %', { progress })}
                </p>
                <div class="vat-progress" role="progressbar" aria-valuemin="0" aria-valuemax={goal}
                  aria-valuenow={progress} aria-label={title}>
                  <span style:transform="scaleX({progress / goal})"></span>
                </div>
              </div>
            {/if}
          </div>
        </header>

        {#if model && !ready}
          <div class="vat-activities">{@render activitySources(model, null, job)}</div>
          <div class="vat-catalyst-slot">
            {#if catalyst}
              {@render catalystPanel(vat, catalyst)}
            {:else if !job}
              <p class="vat-setup-hint">{balance < quote.cost
                ? t('specialIncubators.setupNeedEssence', 'Il manque {amount} poussière d’essence. Recycle des Shards dans le Recycleur.', {
                  amount: formatNumber(quote.cost - balance, 2),
                })
                : t('specialIncubators.lockedLine', 'Le modèle sera immobilisé pendant l’expérience.')}</p>
              {@render memoryProgress(selected)}
            {/if}
          </div>
        {:else}
          <div class="vat-body" class:vat-body-ready={ready && !!model}>
            {#if ready && model}
              {@render extractionPreview(vat, model, fusing)}
              {#if geneticsLevel >= VAT_DNA_LEVEL}
                {@render dnaPanel(vat, job?.dna)}
              {/if}
            {:else if !job}
              <p class="vat-setup-hint">{storedCreatures().length === 0
                ? t('specialIncubators.emptyStorage', 'Place d’abord un Pokémon au stockage pour choisir un modèle.')
                : rows.length === 0 ? t('specialIncubators.noEligibleTemplates', 'Les modèles occupés ou déjà de cette variante ne sont pas admissibles.')
                : t('specialIncubators.templateHint', 'Choisis un modèle pour préparer une variante de niveau 1.')}</p>
            {/if}
          </div>
        {/if}

        <footer class="vat-actions">
          {#if ready}
            <button type="button" class="btn btn-save special-incubator-ready" onclick={() => claimVat(vat)}>
              <img class="vat-pixel-icon" src="img/shiny-logo.png" alt="" width="16" height="16">
              {#if model}
                {fusing
                  ? t('specialIncubators.extractFuse', 'Extraire et fusionner {name}', { name: uiPokemonNameText(game, model.name) })
                  : t('specialIncubators.extract', 'Extraire {name}', { name: uiPokemonNameText(game, model.name) })}
              {:else}
                {t('specialIncubators.extractFallback', 'Extraire le spécimen')}
              {/if}
            </button>
          {:else if job}
            {@const confirming = aborting?.vat === vat && aborting.uid === job.creatureUid}
            <button type="button" class="btn special-incubator-cancel vat-abort" hidden={confirming}
              onclick={(event) => requestAbort(vat, event.currentTarget)}>
              {t('specialIncubators.cancel', 'Abandonner l’expérience')}
            </button>
            {#if confirming}
              <div class="vat-abort-panel" role="group" aria-labelledby="vat-abort-warning-{vat}">
                <p id="vat-abort-warning-{vat}">{t('specialIncubators.abortWarning', 'Remboursement : {amount} {currency}. La progression est perdue et les Shards injectés restent consommés.', {
                  amount: formatNumber(job.dustSpent, 2), currency: refundDustLabel(vat, job),
                })}</p>
                <div class="vat-abort-actions">
                  <button type="button" class="btn btn-save" {@attach (node) => node.focus()} onclick={() => dismissAbort(true)}>
                    {t('specialIncubators.abortKeep', 'Continuer l’expérience')}
                  </button>
                  <button type="button" class="btn special-incubator-cancel vat-abort" onclick={() => confirmAbort(vat)}>
                    {t('specialIncubators.abortConfirm', 'Confirmer l’abandon')}
                  </button>
                </div>
              </div>
            {/if}
          {:else if selected}
            <button type="button" class="btn btn-save special-incubator-start" disabled={balance < quote.cost}
              onclick={() => startVat(vat)}>
              <span class={['vat-price', { short: balance < quote.cost }]}>
                <img src="img/essence-dust.png" class="essence-dust-inline" alt="" />
                {t('specialIncubators.startWithCost', 'Lancer · {amount} poussière d’essence', { amount: formatNumber(quote.cost, 2) })}
              </span>
            </button>
          {:else}
            <button type="button" class="btn special-incubator-cancel" disabled={rows.length === 0}
              aria-haspopup="dialog" aria-expanded={picker?.vat === vat && !picker.preheat} onclick={() => openPicker(vat)}>
              {t('specialIncubators.chooseTemplate', 'Choisir un modèle')}
            </button>
          {/if}
        </footer>
      </section>
    {/each}
  </div>
  {#if geneticsLevel >= VAT_PREHEAT_UNLOCK_LEVEL}
    <details class="vat-preheat">
      <summary>{t('specialIncubators.preheatTitle', 'Préchauffage · {used}/{capacity} emplacements', {
        used: snapshot.preheats.length, capacity: preheatCapacity,
      })}</summary>
      {#if snapshot.preheats.length > 0}
        <div class="vat-preheat-jobs">
          {#each snapshot.preheats as preheat (preheat.creatureUid)}
            {@const template = storedCreatureByUid(preheat.creatureUid)}
            {@const quote = dustQuote(template)}
            {@const blocker = preheatBlocker(preheat, template, quote.cost)}
            {@const occupied = !!template && !!snapshot[preheat.vat]}
            {@const transferLabel = t('specialIncubators.preheatTransfer', 'Transférer · {cost} poussière d’essence', { cost: formatNumber(quote.cost, 2) })}
            {@const heating = t('specialIncubators.preheatHeating', 'Chauffe : {progress} % / {max} % max', {
              progress: specialIncubatorPreheatProgress(preheat), max: VAT_PREHEAT_MAX,
            })}
            <section class="vat-preheat-entry" aria-labelledby="vat-preheat-name-{preheat.creatureUid}">
              <header class="vat-preheat-console">
                <div class="vat-preheat-chamber" aria-hidden="true">
                  <img src={template ? spriteUrl(template) : GEN5_SUBSTITUTE_SPRITE}
                    class={['vat-preheat-sprite', { 'is-shadow': !!template?.isShadow }]}
                    alt="" width="48" height="48" onerror={onSpriteError}>
                </div>
                <div class="vat-preheat-summary">
                  <h4 id="vat-preheat-name-{preheat.creatureUid}">{template
                    ? uiPokemonNameText(game, template.name)
                    : t('specialIncubators.preheatMissingShort', 'Modèle absent')}</h4>
                  <span class="vat-preheat-target">
                    <img src={preheat.vat === 'chromatic' ? 'img/shiny-logo.png' : 'img/shadow-aura.png'} alt="" width="14" height="14">
                    {t('specialIncubators.preheatTarget', 'Cible : {vat}', { vat: vatTitle(preheat.vat) })}
                  </span>
                  <p class="vat-preheat-heating" aria-live="polite">{heating}</p>
                  <progress class="vat-preheat-meter" max={VAT_PREHEAT_MAX}
                    value={specialIncubatorPreheatProgress(preheat)} aria-label={heating}></progress>
                  {@render memoryProgress(template)}
                </div>
                <div class="vat-preheat-actions">
                  <button type="button" class="btn btn-save vat-preheat-transfer" disabled={!!blocker}
                    aria-label={occupied && blocker ? `${blocker.label}. ${transferLabel}` : transferLabel}
                    aria-describedby={blocker ? `vat-preheat-status-${preheat.creatureUid}` : undefined}
                    onclick={() => transferPreheat(preheat)}>
                    <span class="vat-price">
                      <img src="img/essence-dust.png" class="essence-dust-inline" alt="" />
                      {occupied
                        ? t('specialIncubators.preheatTransferOccupied', 'Cuve occupée · {cost}', { cost: formatNumber(quote.cost, 2) })
                        : t('specialIncubators.preheatTransferShort', 'Transférer · {cost}', { cost: formatNumber(quote.cost, 2) })}
                    </span>
                  </button>
                  <div class="vat-preheat-remove">
                    <button type="button" class="btn special-incubator-cancel"
                      aria-label={t('specialIncubators.preheatRemove', 'Retirer du préchauffage')}
                      aria-describedby="vat-preheat-remove-{preheat.creatureUid}"
                      onclick={() => game && cancelSpecialIncubatorPreheat(game, preheat.creatureUid)}>
                      {t('specialIncubators.preheatRemoveShort', 'Retirer')}
                    </button>
                    {@render infoTip(`vat-preheat-remove-${preheat.creatureUid}`,
                      t('specialIncubators.preheatRemoveHelp', 'Effet du retrait'),
                      t('specialIncubators.preheatRemoveHint', 'Retirer le modèle efface sa progression de préchauffage.'), true)}
                  </div>
                  {#if blocker}
                    {#if occupied}
                      <span class="sr-only" id="vat-preheat-status-{preheat.creatureUid}">{blocker.description}</span>
                    {:else}
                      <div class="vat-preheat-status">
                        {@render infoTip(`vat-preheat-status-${preheat.creatureUid}`, blocker.label, blocker.description)}
                      </div>
                    {/if}
                  {/if}
                </div>
              </header>
              {#if template}
                <div class="vat-preheat-activities">{@render activitySources(template, preheat)}</div>
              {/if}
            </section>
          {/each}
        </div>
      {/if}
      {#if snapshot.preheats.length < preheatCapacity}
        <p>{t('specialIncubators.preheatExplain', 'Prépare gratuitement le prochain modèle. Chaque activité peut ajouter {limit} %, jusqu’à {max} % au total. La poussière d’essence est payée au transfert.', {
          limit: VAT_PREHEAT_SOURCE_LIMIT, max: VAT_PREHEAT_MAX,
        })}</p>
        <div class="vat-mastery-actions">
          {#each vats as vat (vat)}
            <button
              type="button"
              class="btn special-incubator-cancel"
              aria-haspopup="dialog"
              aria-expanded={picker?.vat === vat && picker.preheat}
              disabled={storageRows(vat).length === 0}
              onclick={() => openPicker(vat, true)}
            >{t('specialIncubators.preheatChoose', 'Préchauffer · {vat}', { vat: vatTitle(vat) })}</button>
          {/each}
        </div>
      {/if}
    </details>
  {/if}
  {#if picker}
    {@const title = picker.preheat
      ? t('specialIncubators.preheatChoose', 'Préchauffer · {vat}', { vat: vatTitle(picker.vat) })
      : vatTitle(picker.vat)}
    <dialog class="stats-content vat-picker" {@attach attachPickerDialog} aria-labelledby="vat-picker-title"
      oncancel={(event) => { event.preventDefault(); closePicker(); }}>
      <div class="stats-header vat-picker-head">
        <h2 class="vat-picker-title" id="vat-picker-title">{title}</h2>
        <button type="button" class="stats-close" aria-label={t('specialIncubators.pickerClose', 'Fermer')}
          onclick={() => closePicker()}>
          <span aria-hidden="true">×</span>
        </button>
      </div>
      <div class="storage-controls vat-picker-tools">
        <div class="storage-filters-row vat-picker-filters">
          <input
            {@attach attachPickerSearch}
            class="storage-filters-row__search vat-picker-search"
            type="search"
            placeholder={t('specialIncubators.pickerSearch', 'Rechercher par nom…')}
            aria-label={t('specialIncubators.pickerSearch', 'Rechercher par nom…')}
            bind:value={pickerQuery}
            oninput={resetPickerScroll}
          />
          <select class="storage-filters-row__select vat-picker-rarity" bind:value={pickerRarity} onchange={resetPickerScroll}
            aria-label={t('specialIncubators.pickerRarity', 'Rareté')}>
            <option value="all">{t('specialIncubators.pickerAllRarities', 'Toutes les raretés')}</option>
            {#each Object.values(RARITY) as rarity (rarity)}
              <option value={rarity}>{rarityLabel(rarity)}</option>
            {/each}
          </select>
          <select class="storage-filters-row__select vat-picker-variant" bind:value={pickerVariant} onchange={resetPickerScroll}
            aria-label={t('specialIncubators.pickerVariant', 'Variante')} aria-describedby="vat-picker-eligibility">
            <option value="all">{t('specialIncubators.pickerAllVariants', 'Toutes variantes')}</option>
            <option value="normal">{t('specialIncubators.pickerNormalVariants', 'Normaux')}</option>
            <option value="shiny" disabled={picker.vat === 'chromatic'}>{t('specialIncubators.pickerSortShiny', 'Chromatiques')}</option>
            <option value="shadow" disabled={picker.vat === 'shadow'}>{t('specialIncubators.pickerSortShadow', 'Ombres')}</option>
          </select>
        </div>
        <div class="vat-picker-controls" role="group" aria-label={t('specialIncubators.pickerSort', 'Trier par')}>
          {#each PICKER_SORT_OPTIONS as option (option.key)}
            {#if (option.key !== 'shiny' || picker.vat === 'shadow') && (option.key !== 'shadow' || picker.vat === 'chromatic')}
              {@const active = pickerSort === option.key}
              {@const label = t(`specialIncubators.${option.labelKey}`, option.fallback)}
              <button type="button" class="sort-btn vat-picker-sort-btn" class:active class:asc={active && !pickerDescending}
                data-sort={option.key} aria-pressed={active}
                aria-label={active ? `${label}, ${t(pickerDescending ? 'specialIncubators.pickerDescending' : 'specialIncubators.pickerAscending', pickerDescending ? 'Tri décroissant' : 'Tri croissant')}` : label}
                onclick={() => changePickerSort(option.key)}>{label}</button>
            {/if}
          {/each}
        </div>
        <p class="vat-picker-count" role="status">{t('specialIncubators.pickerResults', '{count} / {total} Pokémon', {
          count: pickerRows.length, total: pickerCandidates.length,
        })}</p>
        <p class="vat-picker-count" id="vat-picker-eligibility">{picker.vat === 'chromatic'
          ? t('specialIncubators.pickerChromaticHint', 'Les Pokémon déjà chromatiques ou réservés ne sont pas proposés.')
          : t('specialIncubators.pickerShadowHint', 'Les Pokémon déjà ombres ou réservés ne sont pas proposés.')}</p>
      </div>
      <div class="vat-picker-scroll" {@attach attachPickerScroll} onscroll={onPickerScroll}>
        {#if pickerRows.length === 0}
          <p class="vat-empty">{t('specialIncubators.pickerEmpty', 'Aucun Pokémon correspondant.')}</p>
        {:else}
          {#if pickerWindow.top > 0}
            <div class="vat-picker-spacer" style:height="{pickerWindow.top}px" aria-hidden="true"></div>
          {/if}
          <div class="vat-picker-grid" style:--cols={pickerCols}>
            {#each pickerWindow.items as row (row.uid)}
              {@const creature = creatureAt(row.index)}
              {#if creature}
                <button type="button" class="vat-tile" data-picker-uid={row.uid} title={row.name}
                  onkeydown={(event) => onPickerTileKey(event, row.uid)} onclick={() => chooseRow(row)}>
                  <img
                    class={{ 'is-shadow': !!creature.isShadow }}
                    src={spriteUrl(creature)}
                    alt=""
                    width="36"
                    height="36"
                    onerror={onSpriteError}
                  />
                  <span class="vat-tile-name">
                    {#if row.isShiny}<span class="vat-variant-shiny" role="img" aria-label={t('specialIncubators.variantWordChromatic', 'chromatique')}>✦</span>{/if}
                    {#if row.isShadow}<span class="vat-variant-shadow" role="img" aria-label={t('specialIncubators.variantWordShadow', 'ombre')}>●</span>{/if}
                    {row.name}
                  </span>
                  <span class="vat-tile-meta">
                    <span>{t('state.levelShort', 'Nv.')} {creature.level ?? 1}</span>
                    <span class="vat-rarity vat-rarity-{speciesRarity(creature)}">{rarityLabel(speciesRarity(creature))}</span>
                  </span>
                  <span class="vat-tile-shards">{formatNumber(row.shards)} Shards</span>
                </button>
              {/if}
            {/each}
          </div>
          {#if pickerWindow.bottom > 0}
            <div class="vat-picker-spacer" style:height="{pickerWindow.bottom}px" aria-hidden="true"></div>
          {/if}
        {/if}
      </div>
    </dialog>
  {/if}
</div>

<style>
